package com.musicplaylist.controller;
import com.musicplaylist.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/playlists/create") public class PlaylistServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Integer uid=Auth.userId(q);if(uid==null){p.sendRedirect(q.getContextPath()+"/login");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO playlists(name,user_id) VALUES(?,?)")){s.setString(1,q.getParameter("name").trim());s.setInt(2,uid);s.executeUpdate();p.sendRedirect(q.getContextPath()+"/dashboard");}catch(SQLException x){throw new ServletException(x);}}}